with n as (select h.* from week_history h where h.batch=(select max(x.batch) from week_history x where x.week_start=h.week_start) and h.week_start in ('2026-10-17','2026-10-24') and h.in_list and h.change_note<>'' and h.change_note<>'-' and h.change_note !~* 'crdt|credit')
select json_build_object('ex',(select json_agg(x) from (select n.week_start,c.name,c.agency_ref,left(n.request,25) request,left(n.change,25) change,left(n.change_note,70) note from n join customers c on lower(regexp_replace(c.agency_ref,'\s','','g'))=n.ref_n where c.active order by n.week_start desc, random() limit 6) x)) r;
